import * as regex from './regex.js';
class TokenTypeImpl {
    constructor(pattern, parser, stringifier) {
        this.pattern = pattern;
        this.parser = parser;
        this.stringifier = stringifier;
        if (pattern.automaton.isOptional) {
            throw new Error("Token types cannot have patterns that match empty strings");
        }
    }
    parse(lexeme) {
        return this.parser(lexeme);
    }
    stringify(value) {
        return this.stringifier(value);
    }
    token(lexeme, position) {
        return new Token(this, lexeme, position);
    }
    parsedAs(parser) {
        return new TokenTypeImpl(this.pattern, parser, this.stringifier);
    }
    stringifiedAs(serializer) {
        return new TokenTypeImpl(this.pattern, this.parser, serializer);
    }
    map(to, from) {
        return new TokenTypeImpl(this.pattern, s => to(this.parse(s)), v => this.stringify(from(v)));
    }
    random(position) {
        const lexeme = this.pattern.random();
        return new Token(this, lexeme, position);
    }
    replacing(token) {
        const lexeme = this.pattern.random();
        return new Token(this, lexeme, token.position, token);
    }
}
export const error = new TokenTypeImpl(regex.charNotIn("\u0000-\uffff"), s => new Error(s), s => s.message);
export const eof = new TokenTypeImpl(regex.word("\u0000EOF\u0000"), s => null, s => "");
export function string(pattern) {
    return new TokenTypeImpl(pattern, s => s, s => s);
}
export function float(pattern) {
    return new TokenTypeImpl(pattern, s => Number.parseFloat(s), n => n.toPrecision());
}
export function integer(pattern) {
    return new TokenTypeImpl(pattern, s => Number.parseInt(s), n => n.toFixed(0));
}
export function boolean(t = "true", f = "false") {
    return new TokenTypeImpl(regex.word(t).or(regex.word(f)), s => s === t, b => b ? t : f);
}
export function keyword(word) {
    return new TokenTypeImpl(regex.word(word), _ => word, _ => word);
}
export function keywords(firstWord, ...otherWords) {
    return new TokenTypeImpl(regex.choice(regex.word(firstWord), ...otherWords.map(w => regex.word(w))), w => w, w => w);
}
export function op(op) {
    return keyword(op);
}
export function ops(firstOp, ...otherOps) {
    return keywords(firstOp, ...otherOps);
}
export function delimiter(del) {
    return keyword(del);
}
export function delimiters(firstDel, ...otherDels) {
    return keywords(firstDel, ...otherDels);
}
export class Token {
    constructor(tokenType, lexeme, position, replacedToken = null) {
        this.tokenType = tokenType;
        this.lexeme = lexeme;
        this.position = position;
        this.replacedToken = replacedToken;
        this.value = tokenType.parse(lexeme);
    }
}
